# Simple horizontal gap rule:
# For each row with >= 2 fg cells, fill bg cells between leftmost and rightmost fg

def apply_horizontal_gap_rule(grid, bg_val=9, fg_val=8, fill_val=2):
    result = [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    for r in range(rows):
        row = grid[r]
        fg_cols = [c for c in range(cols) if row[c] == fg_val]

        if len(fg_cols) >= 2:
            # Fill all bg cells between leftmost and rightmost fg
            left = min(fg_cols)
            right = max(fg_cols)
            for c in range(left + 1, right):
                if row[c] == bg_val:
                    result[r][c] = fill_val
    return result

